message.content:
{
  "maturity": "initial",
  "focalEvent": {
    "label": "Loss of instrument-air pressure at RHOB while crew U-A/U-B prepared boundary for #1 slab caster (1SC) compressor/dryer maintenance.",
    "detail": "At ~10:00 AM on May 20, 2024, during Turn 2. Work paused by 10:02; air restored by ~10:07. No injuries reported. Origin of interruption (source vs distribution) unknown.",
    "status": "supported",
    "sourceIds": [
      "incident-description"
    ],
    "specialistIds": []
  },
  "nodes": [
    {
      "type": "condition",
      "label": "Crew U-A/U-B held current Utilities operating qualification and energy-control authorization at shift start.",
      "detail": "Recorded in assignment extract (IA-S03). Does not confirm what they observed or did on the job.",
      "status": "supported","sourceIds":[
        "7e69d300-c57e-40a8-bb37-35a61073ff33#1",
        "claim-1a6reg3"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Work package cover (IA-S02) indicates the temporary instruction attachment field was blank at issue time.",
      "detail": "Blank field suggests no approved temporary instruction attached to support boundary preparation before acceptance signature.",
      "status": "supported","sourceIds":[
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "claim-gyysd1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Field execution record (WO-527-E) was blank at folder issue.",
      "detail": "Blank field implies no recorded boundary verification or valve-state documentation before the interruption occurred.",
      "status": "unknown","sourceIds":[
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "claim-gyysd1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Area directory (IA-D01) states it is a location index and does not establish valve positions or pressure availability at any specific time.",
      "detail": "Directory cannot be used to confirm whether valves were open/closed or if air was available when the interruption occurred.",
      "status": "supported","sourceIds":[
        "b678a928-a8d2-472d-bc03-2e1a3dc411e6#1",
        "claim-ivbspk"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "No evidence confirms whether crew saw recent changes or used a different version of the equipment-location sheet (DW-1SC-17 Revision A).",
      "detail": "Training extract does not state which configuration drawing was seen; no record that a change briefing occurred.",
      "status": "unknown","sourceIds":[
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "claim-2x4nrr"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Shift log records 'boundary preparation in progress' at 09:48 but does not identify point of interruption or valve states.",
      "detail": "Log entry confirms work stage (preparation) and pending release, but provides no physical evidence of where/when the air failed.",
      "status": "partially-supported","sourceIds":[
        "24ec1587-92e9-4320-82c2-30368d834f1d#1",
        "claim-7262ne"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Maintenance acceptance signature was not yet signed at notification time.",
      "detail": "Signature field is a work-stage record; its absence does not prove valve state but indicates boundary release had not been formally accepted before the event.",
      "status": "supported","sourceIds":[
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "claim-gyysd1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "RHOB PLC low-pressure input (AL-44) active below 4.5 bar; clears above 5.0 bar.",
      "detail": "Alarm logic defines the threshold for 'air-low' indication but does not identify which physical point or valve caused the drop.",
      "status": "supported","sourceIds":[
        "da0260c0-7d49-43e8-b074-da2a14c7d59c#1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Point register maps AL-44 to receiving-header pressure condition, not compressor trip contact.",
      "detail": "Alarm text 'COMP FAULT' is a legacy template; actual signal mapped to header pressure drop at RHOB station.",
      "status": "supported","sourceIds":[
        "da0260c0-7d49-43e8-b074-da2a14c7d59c#1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Work scope was planned maintenance and inspection of 1SC dryer group D-101; receiving operation RHOB instrument-air service.",
      "detail": "Defines the system boundary under preparation but does not specify which valves or isolation points were intended to be secured before air loss.",
      "status": "supported","sourceIds":[
        "eaee59fe-70f4-4876-a21d-780814412078#1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Daily work briefing (2024-05-20) listed topic '1SC dryer work and RHOB service coordination' with no valve-by-valve content.",
      "detail": "Briefing confirmed assignment but did not document specific isolation steps or verify boundary integrity before air loss.",
      "status": "supported","sourceIds":[
        "eaee59fe-70f4-4876-a21d-780814412078#1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Work folder retained for review after interruption; maintenance deferred.",
      "detail": "Indicates the event was treated as an unplanned deviation requiring investigation before work could resume or be re-planned.",
      "status": "supported","sourceIds":[
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Local controls showing supply complaints at RHOB; request for Utilities attendance.",
      "detail": "Operator observation of abnormal condition triggered the notification but did not identify root cause or location within distribution network.",
      "status": "supported","sourceIds":[
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "No line opening authorized at 10:02.",
      "detail": "Work paused without formal isolation authorization; suggests boundary release had not been completed when air failed.",
      "status": "supported","sourceIds":[
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Shift log does not identify the point at which air supply was interrupted.",
      "detail": "Log entries lack granularity to determine whether failure occurred upstream, downstream, or within distribution network.",
      "status": "partially-supported","sourceIds":[
        "24ec1587-92e9-4320-82c2-30368d834f1d#1",
        "claim-gyysd1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "'Normal band' is operator's entry, not a captured numeric measurement.",
      "detail": "Restoration of indication at 10:07 does not quantify pressure recovery or confirm system integrity beyond alarm reset.",
      "status": "supported","sourceIds":[
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],"specialistIds":[]
    },
    {
      "type": "condition",
      "label": "Synthetic evaluation record; times and entries reconstructed for exercise.",
      "detail": "Evidence packet explicitly states records are synthetic; treat as model-reviewed claims subject to verification against original sources if available.",
      "status": "supported","sourceIds":[
        "incident-description"
      ],"specialistIds":[]
    }
  ],
  "questions": [
    {
      "intent": "Determine whether the blank field execution record (WO-527-E) was filled before or after the air interruption, and what data it contained if any.",
      "text": "Request the completed WO-527-E field execution record to verify boundary verification steps performed by U-A/U-B. Does this document show valve states, isolation confirmations, or acceptance signatures prior to 10:00 AM?",
      "rationale": "A filled record would establish whether procedural controls were executed; a blank one suggests missing documentation but not necessarily physical failure.",
      "evidenceNeeded": [
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "claim-gyysd1"
      ],
      "priority": "high","sourceIds":[
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "claim-gyysd1"
      ],"routedTo":["human","procedure-planning"]
    },
    {
      "intent": "Identify the physical point of air interruption (source, distribution network, or receiving equipment).",
      "text": "Request pressure trend logs from P-U and P-R points between 09:35 and 10:20 to locate where pressure dropped first. Does a drop at P-U indicate upstream source failure; simultaneous drops suggest distribution issue?",
      "rationale": "Point register maps AL-44 to receiving header but does not show full network behavior; trend data could distinguish location of fault.",
      "evidenceNeeded": [
        "da0260c0-7d49-43e8-b074-da2a14c7d59c#1",
        "incident-description"
      ],
      "priority": "high","sourceIds":[
        "da0260c0-7d49-43e8-b074-da2a14c7d59c#1",
        "incident-description"
      ],"routedTo":["equipment-tool"]
    },
    {
      "intent": "Verify whether a recent service-routing change affected the maintenance boundary and if engineering disposition was completed.",
      "text": "Request any change orders or routing-change notices effective between 2024-03-01 (IA-D03 effective date) and May 20, 2024. Does Engineering have approved a revised ECP for the RHOB/1SC boundary?",
      "rationale": "Change records could explain why crew used outdated drawings or missed new isolation points; absence of disposition supports procedural gap hypothesis.",
      "evidenceNeeded":[
        "0ff450fe-49da-4c67-8b42-35449fdad35c#1",
        "eaee59fe-70f4-4876-a21d-780814412078#1"
      ],
      "priority": "medium","sourceIds":[
        "0ff450fe-49da-4c67-8b42-35449fdad35c#1",
        "eaee59fe-70f4-4876-a21d-780814412078#1"
      ],"routedTo":["procedure-planning"]
    },
    {
      "intent": "Confirm whether U-A/U-B received a recent change briefing for the equipment-location sheet (DW-1SC-17).",
      "text": "Request training attendance logs or interview notes indicating if crew reviewed DW-1SC-17 Revision A and any associated change briefings before 09:35 AM.",
      "rationale": "If no briefing occurred, crew may have relied on outdated drawings; this supports a procedural gap but does not prove physical cause of air loss.",
      "evidenceNeeded":[
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "claim-2x4nrr"
      ],
      "priority": "medium","sourceIds":[
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "claim-2x4nrr"
      ],"routedTo":["human"]
    },
    {
      "intent": "Determine if the blank temporary instruction attachment field was intentional or an oversight.",
      "text": "Request work package issue logs to see who prepared IA-S02 and whether a temporary instruction should have been attached per change requirements (IA-D03 Section 3.6).",
      "rationale": "If omission was unintentional, it points to administrative error; if intentional without approval, suggests procedural bypass.",
      "evidenceNeeded":[
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "claim-gyysd1"
      ],
      "priority": "medium","sourceIds":[
        "eaee59fe-70f4-4876-a21d-780814412078#1",
        "claim-gyysd1"
      ],"routedTo":["procedure-planning"]
    }
  ],
  "decision": {
    "summary": "The incident board currently shows a supported focal event with multiple condition nodes. Key gaps remain: (1) physical location of air interruption, (2) content/timing of WO-527-E field execution record, and (3) whether recent changes affected the boundary without crew awareness. Supported conditions include crew qualifications, blank temporary instruction attachment, unsigned acceptance signature, and area directory limitations. Unsupported or unknown nodes reflect missing evidence rather than disproven claims.",
    "evidenceUsed": [
      "incident-description",
      "24ec1587-92e9-4320-82c2-30368d834f1d#1",
      "eaee59fe-70f4-4876-a21d-780814412078#1",
      "7e69d300-c57e-40a8-bb37-35a61073ff33#1",
      "b678a928-a8d2-472d-bc03-2e1a3dc411e6#1",
      "da0260c0-7d49-43e8-b074-da2a14c7d59c#1"
    ],
    "unknowns": [
      "Physical point of air interruption (source vs distribution)",
      "Content and completion status of WO-527-E field execution record",
      "Whether crew received change briefing for DW-1SC-17 Revision A",
      "Reason blank temporary instruction attachment field remained empty"
    ],
    "alternatives": [
      "Air loss originated upstream (source failure) vs within distribution network vs at receiving equipment.",
      "Blank WO-527-E was filled later but not logged, or never completed due to interruption.",
      "Crew used correct drawings despite no documented briefing; change may have been communicated verbally."
    ],
    "confidence": 0.68
  },"evidenceRequests":[
    "eaee59fe-70f4-4876-a21d-780814412078#1",
    "da0260c0-7d49-43e8-b074-da2a14c7d59c#1"
  ]}
